verify.cmd:
node -e 'const fs=require("fs")
const fail=(m)=>{console.error(m);process.exit(1)}
const norm=(s)=>s.replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ")
const rd=(f)=>{try{return norm(fs.readFileSync(f,"utf8"))}catch(e){return null}}
const pk=rd("lib/loom/picker-actions.ts")
const st=rd("components/spaces/loom/space-loom-studio.tsx")
if(pk===null||st===null)process.exit(79)
const q=rd("lib/library/quota.ts")
if(q===null)fail("there is no quota module, so nothing sums what a Space stores and nothing can refuse the next upload")
if(!/export (async )?function loomQuotaFor\(/.test(q))fail("nothing states a cap for a Space, so there is no number an upload can be measured against")
if(!/export async function loomStorageUsed\(/.test(q))fail("nothing sums a Space bytes, so the cap has nothing to compare with")
const capOf=(t)=>{const m=q.match(new RegExp("\\b"+t+":\\s*(\\d+)\\s*\\*\\s*GB"));return m?Number(m[1]):null}
if(!/asSpacePlan\(/.test(q)||!/LOOM_STORAGE_CAP_BYTES\s*:\s*Record<SpacePlan/.test(q)||capOf("free")===null||!(capOf("business")>capOf("free")))fail("the cap is not keyed by plan tier, or a paid tier holds no more than free, so the cap cannot differ by what a Space pays for")
const i=pk.indexOf("export async function uploadLoomImage(")
if(i<0)fail("uploadLoomImage is gone, so there is no Space upload door to gate")
const body=pk.slice(i,pk.indexOf("\n}",i))
const delegated=/return uploadAuthorizedLoomImage\(spaceId, caller\.id, formData\)/.test(body)
const canonical=delegated?rd("lib/loom/authorized-image-upload.ts"):body
if(!canonical)fail("the canonical upload pipeline is missing")
const gate=canonical.indexOf("loomAdmits(")
const upload=canonical.indexOf(".upload(")
if(gate<0||upload<0||gate>upload)fail("the canonical Space upload pipeline never asks the budget before storing bytes")
if(!/if \(!verdict\.ok\) return \{ error: verdict\.error \}/.test(canonical))fail("the upload pipeline ignores the budget refusal")
if(!/data-loom-quota/.test(st))fail("the Space Loom Studio shows no meter, so an operator learns about the cap from a refusal and never before")
console.log("ok")'
